      ($str$casting_vertical_automatic$str$, $str$Loramendi VMM-80120-B (43"x40")$str$, 2.25, 236.06, 14.75, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B2-7","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"Loramendi VMM-80120-B (43\"x40\")"}$jsonb$::jsonb),
      ($str$casting_vertical_automatic$str$, $str$Loramendi VMM-80120-C (47"x43")$str$, 2.25, 278.48, 15.48, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B2-7","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"Loramendi VMM-80120-C (47\"x43\")"}$jsonb$::jsonb),
      ($str$casting_vertical_automatic$str$, $str$Loramendi VMM-6080-D (34"x25")$str$, 2.25, 206.37, 12.14, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B2-7","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"Loramendi VMM-6080-D (34\"x28\")"}$jsonb$::jsonb),
      ($str$casting_x_ray$str$, $str$X-ray Machine$str$, 2.99, 1.92, 9.82, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B2-8","india_sector":"World Average","india_machine_type":null,"india_review_note":"Indirect > direct overhead - unusual, confirm in source","india_name_as_transcribed":"XrayMachine"}$jsonb$::jsonb)
  ) v(machine_class, name, labor, direct, indirect, extra)
  LOOP
    SELECT usa.id INTO usa_id FROM mhr_records usa
    WHERE usa.location = 'USA' AND usa.machine_class = r.machine_class
      AND lower(trim(usa.machine_name)) = lower(trim(r.name))
    LIMIT 1;
    IF usa_id IS NULL THEN
      missing := missing || r.name;
    ELSIF NOT EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = 'India'
                      AND m.machine_class = r.machine_class AND lower(trim(m.machine_name)) = lower(trim(r.name))) THEN
      EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records usa WHERE usa.id = $1', cols, sel)
        USING usa_id, r.direct, r.indirect, r.labor, r.extra;
      n := n + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'Casting India rows cloned from a USA twin: %', n;
  IF cardinality(missing) > 0 THEN
    RAISE NOTICE 'No USA twin (run part 1 first): %', array_to_string(missing, '; ');
  END IF;
END
$india848$;

-- ── 2b. India-only machines: their own India row (rates only).
INSERT INTO mhr_records (machine_class, location, machine_name, currency_code, country_code, source_type, process_group, wage_grade,
  direct_overhead_rate, indirect_overhead_rate, benchmark_direct_overhead_rate_usd_hr, benchmark_indirect_overhead_rate_usd_hr,
  total_machine_hour_rate, mhr_usd_per_hour, usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total, specs, benchmark_source_key)
SELECT v.machine_class, v.location, v.machine_name, v.currency_code, v.country_code, v.source_type, v.process_group, v.wage_grade,
  v.direct::numeric, v.indirect::numeric, v.direct::numeric, v.indirect::numeric,
  ROUND((v.direct + v.indirect)::numeric, 2), ROUND((v.direct + v.indirect)::numeric, 2), v.labor::numeric, v.labor::numeric, v.labor::numeric,
  v.specs, v.benchmark_source_key
FROM (VALUES
  ($str$casting_die_casting$str$, $str$India$str$, $str$QUANTUM QDC280$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Casting$str$, $str$3 - Casting$str$, 18.79, 1.95, 2.25, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B1-4","india_sector":"World Average","india_machine_type":null,"india_review_note":"VERIFY: process group unconfirmed (die-casting machine names); low-res source","india_name_as_transcribed":"QUANTUM QDC280"}$jsonb$::jsonb, $str$Die Casting:QUANTUM QDC280:India$str$),
  ($str$casting_manual_std_moldmaking$str$, $str$India$str$, $str$EMI-212 Ram-Jolt Squeeze Molding Line (12x14x4in)$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Casting$str$, $str$3 - Casting$str$, 2.6, 1.41, 2.25, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B1-12|B1-13","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"EMI-212 Ram-Jolt Squeeze Molding Line (12x14x4in)"}$jsonb$::jsonb, $str$Manual Std Moldmaking:EMI-212 Ram-Jolt Squeeze Molding Line (12x14x4in):India$str$),
  ($str$casting_manual_std_moldmaking$str$, $str$India$str$, $str$EMI-212 Ram-Jolt Squeeze Molding Line (12x18x8in)$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Casting$str$, $str$3 - Casting$str$, 2.6, 1.41, 2.25, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B1-12|B1-13","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"EMI-212 Ram-Jolt Squeeze Molding Line (12x18x8in)"}$jsonb$::jsonb, $str$Manual Std Moldmaking:EMI-212 Ram-Jolt Squeeze Molding Line (12x18x8in):India$str$),
  ($str$casting_manual_std_moldmaking$str$, $str$India$str$, $str$EMI-214 Ram-Jolt Squeeze Molding Line (14x20x4in)$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Casting$str$, $str$3 - Casting$str$, 3.64, 1.47, 2.25, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B1-12|B1-13","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"EMI-214 Ram-Jolt Squeeze Molding Line (14x20x4in)"}$jsonb$::jsonb, $str$Manual Std Moldmaking:EMI-214 Ram-Jolt Squeeze Molding Line (14x20x4in):India$str$),
  ($str$casting_manual_std_moldmaking$str$, $str$India$str$, $str$EMI-722 Rota-Lift Molding Line (30x30x18in)$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Casting$str$, $str$3 - Casting$str$, 12.59, 2.13, 2.25, $jsonb${"india_source_file":"memory/Casting/Indian data/sand_casting_machine_rates_full.csv","india_source_image":"B1-12|B1-13","india_sector":"World Average","india_machine_type":null,"india_review_note":null,"india_name_as_transcribed":"EMI-722 Rota-Lift Molding Line (30x30x18in)"}$jsonb$::jsonb, $str$Manual Std Moldmaking:EMI-722 Rota-Lift Molding Line (30x30x18in):India$str$)
) AS v(machine_class, location, machine_name, currency_code, country_code, source_type, process_group, wage_grade, direct, indirect, labor, specs, benchmark_source_key)
WHERE NOT EXISTS (
  SELECT 1 FROM mhr_records m WHERE m.location = 'India' AND m.machine_class = v.machine_class
    AND lower(trim(m.machine_name)) = lower(trim(v.machine_name))
